// Fixtures for VITE_MOCK=1. fixtures.json was generated by running the real flag engine,
// decision table and template_fallback (src/lablens) over data/ground_truth rows, so shapes and
// wording match what the API returns:
//   D01 normal CBC · D05 lipid, mild TG (package) · D03 critical platelets + WBC with the
//   critical-override warning (WBC edited: printed range calls 1.8 normal) · D16 (mock only)
//   D01 with an unrecognised Hb unit ("please verify") and an unsupported test.
import type { components } from "./schema";
import { ApiError } from "./errors";
import raw from "./fixtures.json";
type ReportResult = components["schemas"]["ReportResult"];
type FlaggedTest = components["schemas"]["FlaggedTest"];
type ApiDemoReport = components["schemas"]["DemoReport"];
type SavedReport = components["schemas"]["SavedReport"];
type SaveRequest = components["schemas"]["SaveRequest"];
type TrendResponse = components["schemas"]["TrendResponse"];
type OverlapItem = components["schemas"]["OverlapItem"];

export function delay<T>(value: T, ms = 300): Promise<T> {
  return new Promise((r) => setTimeout(() => r(value), ms));
}

const fixtures = raw as unknown as Record<string, ReportResult>;

// Same shape as GET /v1/demo/reports (titles from data/ground_truth/index.json).
const demoList: ApiDemoReport[] = [
  { id: "D01", title: "CBC, all normal", panel: "cbc", category: "normal", test_count: 14, pdf_url: "/v1/demo/reports/D01.pdf" },
  { id: "D05", title: "Lipid profile, mildly high triglycerides (package pattern)", panel: "lipid", category: "abnormal", test_count: 7, pdf_url: "/v1/demo/reports/D05.pdf" },
  { id: "D03", title: "CBC, critically low platelets", panel: "cbc", category: "critical", test_count: 14, pdf_url: "/v1/demo/reports/D03.pdf" },
  { id: "D16", title: "CBC, haemoglobin unit not recognised (mock only)", panel: "cbc", category: "held", test_count: 14, pdf_url: "/v1/demo/reports/D16.pdf" },
];
export function listDemoReports(): Promise<{ reports: ApiDemoReport[] }> {
  return delay({ reports: demoList });
}

export async function getReport(id: string): Promise<ReportResult> {
  const r = fixtures[id];
  if (!r) throw new ApiError(404, "not_found", "Report not found or expired.");
  return delay(r);
}

export function createReport(_file: File, _type: string): Promise<ReportResult> {
  fixtures.upload_mock = { ...fixtures.D05, report_id: "upload_mock" };
  return delay(fixtures.upload_mock, 800);
}

// ---- History (in memory, signed-in mock user) ----
const pick = (r: ReportResult, ids: string[]) => r.tests.filter((x) => x.test_id && ids.includes(x.test_id));
const withValue = (x: FlaggedTest, v: number, extra: Partial<FlaggedTest> = {}): FlaggedTest => ({
  ...x, value: { raw: String(v), number: v, comparator: "=" }, ...extra,
});
function saved(id: string, date: string, tests: FlaggedTest[], sha: string): SavedReport {
  return { saved_report_id: id, user_id: "mock-sub", report_date: date, date_source: "user_entered",
    file_sha256: sha, tests, consent_notice_version: "2026-11-v1", saved_at: `${date}T10:00:00Z` };
}
function seed(): SavedReport[] {
  const cbc = fixtures.D01, crit = fixtures.D03, lipid = fixtures.D05;
  const [hb, plt] = pick(cbc, ["HB", "PLT"]);
  const critPlt = pick(crit, ["PLT"])[0];
  return [
    saved("s1", "2025-12-10", [withValue(hb, 12.4, { ref: { raw: "12.0 - 15.0", low: 12, high: 15, source: "report" } }), withValue(plt, 260)], "sha1"),
    saved("s2", "2026-03-18", [withValue(hb, 11.6, { flag: "low", severity: "mild", ref: { raw: "11.5 - 16.0", low: 11.5, high: 16, source: "report" } }), withValue(plt, 210)], "sha2"),
    // A lab that printed haemoglobin in g/L: no exact conversion is assumed, so "different unit".
    saved("s3", "2026-06-02", [withValue(hb, 128, { unit: "g/L", unit_raw: "g/L", ref: { raw: "120 - 150", low: 120, high: 150, source: "report" } }), critPlt], "sha3"),
    saved("s4", "2026-09-05", [...cbc.tests.filter((x) => ["HB", "PLT", "WBC"].includes(x.test_id ?? "")), ...pick(lipid, ["TG"])], "sha4"),
  ];
}
let history: SavedReport[] = seed();
const savedSha = new Map<string, string>(); // report_id -> saved_report_id

export function listHistory(): Promise<SavedReport[]> {
  return delay([...history].sort((a, b) => b.report_date.localeCompare(a.report_date)));
}
export function getTrend(testId: string): Promise<TrendResponse> {
  const canonical = new Map<string, string>();
  const points = [...history].sort((a, b) => a.report_date.localeCompare(b.report_date)).flatMap((s) =>
    s.tests.filter((x) => x.test_id === testId).map((x) => {
      if (!canonical.has(testId)) canonical.set(testId, x.unit ?? "");
      return { report_date: s.report_date, saved_report_id: s.saved_report_id, value: x.value, unit: x.unit,
        ref: x.ref, flag: x.flag, is_critical: x.is_critical, different_unit: (x.unit ?? "") !== canonical.get(testId) };
    }));
  return delay({ test_id: testId, points });
}
export function deleteHistoryItem(id: string): Promise<void> {
  if (!history.some((s) => s.saved_report_id === id)) return Promise.reject(new ApiError(404, "not_found", "Not found."));
  history = history.filter((s) => s.saved_report_id !== id);
  return delay(undefined);
}
export function deleteAllHistory(): Promise<void> {
  history = [];
  return delay(undefined);
}
export async function saveReport(reportId: string, body: SaveRequest): Promise<SavedReport> {
  const r = fixtures[reportId];
  if (!r) throw new ApiError(404, "not_found", "Report not found or expired.");
  const prev = savedSha.get(reportId);
  const prevSaved = prev && history.find((s) => s.saved_report_id === prev);
  if (prevSaved) {
    const on = prevSaved.saved_at.slice(0, 10);
    throw new ApiError(409, "already_saved", `This report is already saved (saved on ${on}).`, { reason: "already_saved", saved_on: on });
  }
  const choice = body.overlap_choice ?? {};
  const overlaps: OverlapItem[] = history.filter((s) => s.report_date === body.report_date).flatMap((s) =>
    r.tests.filter((n) => n.test_id && !(n.test_id in choice)).flatMap((n) =>
      s.tests.filter((e) => e.test_id === n.test_id).map((e) => ({
        test_id: n.test_id!, report_date: s.report_date, existing_saved_report_id: s.saved_report_id, existing: e, new: n }))));
  if (overlaps.length) throw new ApiError(409, "overlap", "Some tests are already saved for this date.", { reason: "overlap", overlaps });
  let tests = r.tests;
  for (const [tid, c] of Object.entries(choice)) {
    if (c === "keep_existing") tests = tests.filter((x) => x.test_id !== tid);
    if (c === "keep_new") history = history.map((s) => s.report_date === body.report_date ? { ...s, tests: s.tests.filter((x) => x.test_id !== tid) } : s);
  }
  const s = saved(`s${Date.now()}`, body.report_date, tests, `sha-${reportId}`);
  s.date_source = r.report_date === body.report_date ? "extracted_confirmed" : "user_entered";
  s.saved_at = new Date().toISOString();
  history = [...history, s];
  savedSha.set(reportId, s.saved_report_id);
  return delay(s);
}
